package diffiehellman

import (
	"errors"
	"math/big"
)

const (
	// GroupID14 RFC-3526 2048-bit MODP Group
	GroupID14 = ""
)

func GetGroupID14() (*big.Int, error) {
	bi, ok := new(big.Int).SetString(GroupID14, 16)
	if !ok {
		return nil, errors.New("could not set big.Int from string")
	}

	return bi, nil
}
